package com.example.examplemod.client.render;

import com.mojang.math.Axis;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.item.ItemDisplayContext;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

import com.example.examplemod.block.entity.PedestalBlockEntity;

public class PedestalBER implements BlockEntityRenderer<PedestalBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public PedestalBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(PedestalBlockEntity be, float partialTick,
                       com.mojang.blaze3d.vertex.PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        ItemStack shown = be.getShownItem();
        if (shown.isEmpty()) return;
        Level level = be.getLevel();
        if (level == null) return;
        pose.pushPose();
        double bob = Math.sin((level.getGameTime() + partialTick) * 0.1) * 0.05;
        pose.translate(0.5, 1.0 + bob, 0.5);
        pose.scale(0.5f, 0.5f, 0.5f);
        pose.mulPose(Axis.YP.rotationDegrees(
                (level.getGameTime() + partialTick) * 1.5f));
        Minecraft.getInstance().getItemRenderer().renderStatic(
                shown, ItemDisplayContext.GROUND, 15728880,
                OverlayTexture.NO_OVERLAY, pose, buffers, level, 0);
        pose.popPose();
    }
}

