package com.example.examplemod.client.render;

import net.minecraft.client.renderer.LightTexture;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.BeaconRingBlockEntity;

public class BeaconRingBER implements BlockEntityRenderer<BeaconRingBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public BeaconRingBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(BeaconRingBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        long t = (be.getLevel() != null ? be.getLevel().getGameTime() : 0) + (long) partialTick;
        for (int i = 0; i < 6; i++) {
            double angle = Math.toRadians(t * 2.0 + i * 60.0);
            double x = 0.5 + Math.cos(angle) * 1.5;
            double z = 0.5 + Math.sin(angle) * 1.5;
            pose.pushPose();
            pose.translate(x, 0.8, z);
            pose.scale(0.15f, 0.15f, 0.15f);
            ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                    Blocks.AMETHYST_BLOCK.defaultBlockState(), pose, buffers,
                    LightTexture.pack(15, 15), OverlayTexture.NO_OVERLAY);
            pose.popPose();
        }
    }
}

