package com.example.examplemod.client.render;

import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.ItemDisplayContext;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.FridgeBlockEntity;

public class FridgeBER implements BlockEntityRenderer<FridgeBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public FridgeBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(FridgeBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        var stack = be.getStoredStack();
        if (stack.isEmpty()) return;
        if (stack.has(DataComponents.FOOD)) {
            renderStack(stack, pose, buffers, 0.4f, 0.9);
        } else if (stack.has(DataComponents.ENCHANTABLE)) {
            renderBlock(Blocks.ENCHANTING_TABLE, pose, buffers, 1.0f, 0.7);
        } else {
            renderBlock(Blocks.BOOKSHELF, pose, buffers, 1.0f, 0.2);
        }
    }

    private void renderStack(net.minecraft.world.item.ItemStack stack,
                             PoseStack pose, MultiBufferSource buffers,
                             float scale, double y) {
        pose.pushPose();
        pose.translate(0.5, y, 0.5);
        pose.scale(scale, scale, scale);
        Minecraft.getInstance().getItemRenderer().renderStatic(stack,
                ItemDisplayContext.GROUND, 15728880,
                OverlayTexture.NO_OVERLAY, pose, buffers, null, 0);
        pose.popPose();
    }

    private void renderBlock(net.minecraft.world.level.block.Block block,
                             PoseStack pose, MultiBufferSource buffers,
                             float scale, double y) {
        pose.pushPose();
        pose.translate(0.5, y, 0.5);
        pose.scale(scale, scale, scale);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                block.defaultBlockState(), pose, buffers, 15728880,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
