import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.util.Mth;
import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.PistonArmBlockEntity;

public class PistonArmBER implements BlockEntityRenderer<PistonArmBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public PistonArmBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    public static double interpolate(double prev, double cur, float partialTick) {
        double v = Mth.lerp(partialTick, prev, cur);
        return Mth.clamp(v, 0.0, 1.0);
    }

    @Override
    public void render(PistonArmBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        double t = interpolate(be.getPrevExtend(), be.getExtend(), partialTick);
        pose.pushPose();
        pose.translate(0.5, 0.3 + t * 0.6, 0.5);
        pose.scale(0.2f, 0.2f, 0.2f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.OBSIDIAN.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

