import net.minecraft.world.level.block.Blocks;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.math.Axis;
import com.example.examplemod.entity.Orb;

public class OrbRenderer extends EntityRenderer<Orb> {
    private static final ResourceLocation TEXTURE =
            ResourceLocation.fromNamespaceAndPath("minecraft", "textures/misc/white.png");

    public OrbRenderer(EntityRendererProvider.Context ctx) {
        super(ctx);
    }

    @Override
    public ResourceLocation getTextureLocation(Orb entity) {
        return TEXTURE; // never sampled: shape rendered via block dispatcher
    }

    @Override
    public void render(Orb entity, float entityYaw, PoseStack pose,
                       MultiBufferSource buffers, int light) {
        var br = this.blockDispatcher(entity).getBlockRenderer();
        float spin = (entity.tickCount + 1.0f) * 3.0f;
        cube(br, pose, buffers, light, Blocks.DIAMOND_BLOCK, 0.4f, 0.2, 0);
        cube(br, pose, buffers, light, Blocks.LAPIS_BLOCK, 0.25f, 0.6, 0);
        cube(br, pose, buffers, light, Blocks.AMETHYST_BLOCK, 0.1f, 0.9, spin);
        super.render(entity, entityYaw, pose, buffers, light);
    }

    private net.minecraft.client.renderer.block.BlockRenderDispatcher blockDispatcher(Orb e) {
        return net.minecraft.client.Minecraft.getInstance().getBlockRenderer();
    }

    private void cube(net.minecraft.client.renderer.block.BlockRenderDispatcher br,
                      PoseStack pose, MultiBufferSource buffers, int light,
                      net.minecraft.world.level.block.Block block,
                      float scale, double y, float spinDeg) {
        pose.pushPose();
        pose.translate(0.5, y, 0.5);
        if (spinDeg != 0) pose.mulPose(Axis.YP.rotationDegrees(spinDeg));
        pose.scale(scale, scale, scale);
        br.renderSingleBlock(block.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

