package com.example.examplemod.client;

import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;

import java.util.List;

public class ItemTooltipHandler {
    public static void onItemTooltip(ItemStack stack, TooltipFlag flag,
                                     List<Component> lines) {
        Item item = stack.getItem();
        int power = stack.getMaxDamage();
        var dmg = stack.getComponents().get(DataComponents.MAX_DAMAGE);
        if (dmg != null) {
            power = dmg;
        }
        lines.add(Component.translatable("exmod.tooltip.power",
                item.getName(stack).getString() + ":" + power));
    }
}

package com.example.examplemod.client;

import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.world.item.ItemStack;

public class BerItemPulseHandler {
    public static void renderItemsInGui(GuiGraphics g, Font font,
                                        ItemStack[] stacks, int x0, int y0,
                                        int cell) {
        int shown = 0;
        for (int i = 0; i < stacks.length && shown < 8; i++) {
            ItemStack s = stacks[i];
            int x = x0 + i * cell;
            if (!s.isEmpty()) {
                g.renderItem(s, x, y0);
                g.renderItemDecorations(font, s, x, y0);
            }
            shown++;
        }
        int overflow = stacks.length - 8;
        if (overflow > 0) {
            g.drawString(font, "+" + overflow, x0 + 7 * cell + 2, y0 + 8, 0xFFFF55);
        }
    }
}

