public class VaseBER implements BlockEntityRenderer<VaseBlockEntity> {
    public VaseBER(BlockEntityRendererProvider.Context ctx) {
    }

    @Override
    public void render(VaseBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        ItemStack stack = be.getStoredStack();
        if (stack.isEmpty()) return;
        renderItem(stack, pose, buffers, 0.35f, 0.5, 0.85, 0.5, 0);
        if (stack.getCount() > 1) {
            renderItem(stack, pose, buffers, 0.12f, 0.68, 0.78, 0.68, 30);
        }
    }

    private void renderItem(ItemStack stack, PoseStack pose,
                            MultiBufferSource buffers, float scale,
                            double x, double y, double z, float rotY) {
        pose.pushPose();
        pose.translate(x, y, z);
        if (rotY != 0) pose.mulPose(Axis.YP.rotationDegrees(rotY));
        pose.scale(scale, scale, scale);
        Minecraft.getInstance().getItemRenderer().renderStatic(stack,
                ItemDisplayContext.FIXED, 15728880, OverlayTexture.NO_OVERLAY,
                pose, buffers, null, 0);
        pose.popPose();
    }
}

