package com.example.examplemod.client.render;

import net.minecraft.client.renderer.LightTexture;
import net.minecraft.util.Mth;

public class EmissiveLightCalc {
    public static float lerpIntToFloat(int a, int b, float t) {
        return Mth.lerp(t, a, b);
    }

    public static int emissiveLight(int worldLight, float glowLevel) {
        float g = Mth.clamp(glowLevel, 0.0f, 1.0f);
        int worldBlock = LightTexture.block(worldLight);
        int worldSky = LightTexture.sky(worldLight);
        int blockLight = Math.round(lerpIntToFloat(worldBlock, 15, g));
        int skyLight = Math.round(lerpIntToFloat(worldSky, 15, g));
        blockLight = Mth.clamp(blockLight, 0, 15);
        skyLight = Mth.clamp(skyLight, 0, 15);
        return LightTexture.pack(blockLight, skyLight);
    }
}

