package com.example.examplemod.client.render;

import net.minecraft.util.Mth;

public class SpinMath {
    public static float continuousAngle(long gameTime, float partialTick,
                                        float degreesPerTick) {
        float total = (gameTime + partialTick) * degreesPerTick;
        return Mth.positiveModulo(total, 360.0f);
    }

    public static float easedProgress(float t) {
        float c = Mth.clamp(t, 0.0f, 1.0f);
        return c * c * (3.0f - 2.0f * c);
    }
}

