package com.example.examplemod.client.render;

import net.minecraft.util.Mth;

public class InterpBuffer {
    private double prev;
    private double cur;

    private InterpBuffer(double initial) {
        this.prev = initial;
        this.cur = initial;
    }

    public static InterpBuffer create(double initial) {
        return new InterpBuffer(initial);
    }

    // called on the client tick thread; render thread reads valueAt.
    // volatile is NOT sufficient: two fields must flip together - a torn
    // pair would lerp across the wrong snapshot. Acceptable here because
    // the worst case is one frame of stale interpolation.
    public void push(double v) {
        prev = cur;
        cur = v;
    }

    public double valueAt(float partialTick) {
        return Mth.lerp(partialTick, prev, cur);
    }

    public boolean isChanged() {
        return prev != cur;
    }
}

