package com.example.examplemod.client.render;

public class FrustumDoc {
    // conservative: real culling uses camera-space frustum planes; this
    // distance test never hides a sphere that is actually visible
    public static boolean sphereIntersectsFrustumLike(
            double cx, double cy, double cz, double radius,
            double camX, double camY, double camZ, double maxDist) {
        double dx = cx - camX, dy = cy - camY, dz = cz - camZ;
        double limit = maxDist + radius;
        return dx * dx + dy * dy + dz * dz <= limit * limit;
    }

    public static double maxSafeRadius() {
        return 32.0;
    }
}

