import org.joml.Matrix4f;
import com.example.examplemod.block.entity.NestedPoseBlockEntity;

public class NestedPoseBER implements BlockEntityRenderer<NestedPoseBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public NestedPoseBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(NestedPoseBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        Matrix4f snapshot = new Matrix4f(pose.last().pose());
        long t = be.getLevel() != null ? be.getLevel().getGameTime() : 0;
        pose.pushPose();
        pose.translate(0.5, 0.0, 0.5);
        pose.pushPose();
        pose.mulPose(Axis.YP.rotationDegrees(t * 1.0f));
        pose.pushPose();
        pose.scale(0.5f, 0.5f, 0.5f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.IRON_BLOCK.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
        pose.popPose();
        pose.popPose();
        // balanced pushes/pops restore the exact matrix
        assert new Matrix4f(pose.last().pose()).equals(snapshot);
    }
}

