import net.minecraft.client.renderer.LightTexture;

public class LightDecode {
    public static String describe(int packedLight) {
        if (packedLight == 15728880) return "bright";
        int b = LightTexture.block(packedLight);
        int s = LightTexture.sky(packedLight);
        if (b == 0 && s == 0) return "dark";
        return "block=" + b + ",sky=" + s;
    }

    public static int packOrBright(int block, int sky) {
        block = MthClamp(block);
        sky = MthClamp(sky);
        return LightTexture.pack(block, sky);
    }

    private static int MthClamp(int v) {
        return Math.max(0, Math.min(15, v));
    }
}

