package com.example.examplemod.client.render;

import java.util.concurrent.ConcurrentHashMap;

public class ReloadAwareCache<K, V> {
    // caches of models/textures MUST be cleared on resource reload (F3+T)
    // or they keep serving stale assets; concurrent map because the render
    // thread and worker threads may touch it simultaneously
    private final ConcurrentHashMap<K, V> backing = new ConcurrentHashMap<>();

    public V computeIfAbsent(K key, java.util.function.Function<K, V> loader) {
        return backing.computeIfAbsent(key, loader);
    }

    public void invalidateAll() {
        backing.clear();
    }

    public int size() {
        return backing.size();
    }
}

package com.example.examplemod.client.render;

public class VersionGuard {
    // 1.21 renders through core-shader JSON pipelines; custom pipelines
    // must be gated per version or they break across updates
    public static String pipelineFor(String mcVersion) {
        if (mcVersion != null && mcVersion.startsWith("1.21")) {
            return "core_shaders";
        }
        if (mcVersion != null && mcVersion.startsWith("1.20")) {
            return "legacy_fixed";
        }
        return "unknown";
    }

    public static boolean requiresShaderReload(String oldV, String newV) {
        return !pipelineFor(oldV).equals(pipelineFor(newV));
    }
}

package com.example.examplemod.client.render;

public class RenderArtifactTriage {
    public static String triage(String symptom) {
        return switch (symptom == null ? "" : symptom) {
            case "flicker" -> "z_fighting_or_sorting";
            case "black_faces" -> "missing_lightmap_or_normal";
            case "stretched" -> "wrong_uv_scale";
            case "invisible" -> "culling_or_empty_geometry";
            default -> "unknown_symptom";
        };
