public class TrophyBER implements BlockEntityRenderer<TrophyBlockEntity> {
    private static final int BUDGET = 12;
    private final BlockEntityRendererProvider.Context ctx;

    public TrophyBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(TrophyBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        int count = Math.min(be.getItemCount(), BUDGET);
        ItemStack trophy = new ItemStack(Items.EMERALD);
        for (int i = 0; i < count; i++) {
            double a = Math.toRadians(i * (360.0 / BUDGET));
            pose.pushPose();
            pose.translate(0.5 + Math.cos(a) * 0.5, 0.4,
                    0.5 + Math.sin(a) * 0.5);
            pose.scale(0.15f, 0.15f, 0.15f);
            Minecraft.getInstance().getItemRenderer().renderStatic(trophy,
                    ItemDisplayContext.FIXED, 15728880,
                    OverlayTexture.NO_OVERLAY, pose, buffers, null, 0);
            pose.popPose();
        }
        if (be.getItemCount() > BUDGET) {
            pose.pushPose();
            pose.translate(0.5, 0.9, 0.5);
            pose.scale(0.1f, 0.1f, 0.1f);
            ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                    Blocks.GOLD_BLOCK.defaultBlockState(), pose, buffers,
                    15728880, OverlayTexture.NO_OVERLAY);
            pose.popPose();
        }
    }
}

