package com.example.examplemod.client.render;

public class CullingCorrectness {
    // conservative box-vs-sphere pre-pass used before frustum checks
    public static boolean isPotentiallyVisible(double[] min, double[] max,
                                               double[] cam, double maxDist) {
        double cx = Math.max(min[0], Math.min(max[0], cam[0]));
        double cy = Math.max(min[1], Math.min(max[1], cam[1]));
        double cz = Math.max(min[2], Math.min(max[2], cam[2]));
        double dx = cam[0] - cx, dy = cam[1] - cy, dz = cam[2] - cz;
        return dx * dx + dy * dy + dz * dz <= maxDist * maxDist;
    }
}

