public class PartialTickDoc {
    // interpolating across a teleport draws a streak across the world:
    // snap to the current position instead
    public static boolean isTeleport(double prev, double cur) {
        return Math.abs(cur - prev) > 8.0;
    }

    public static double stablePosition(double prev, double cur, float partialTick) {
        if (isTeleport(prev, cur)) return cur;
        return prev + (cur - prev) * partialTick;
    }
}

